            "test": "r10",
            "supports": True
        },
        "L1_MLP": {
            "hypothesis": "L1_MLP is a combiner that fuses L0_MLP's frequency computation with direct head writes persisting in the residual stream; ablating L1_MLP (r16) changes predictions significantly (0.1111 instead of 0.3333 for abc-interleaved), and L1_MLP's write changes by mean 560 when L0_MLP is ablated, 820 when L0H0 is ablated, and 3478 when L0H1 is ablated.",
            "test": "r16",
            "supports": True
        }
    }
}

with open('/work/submission.json', 'w') as f:
    json.dump(submission, f, indent=2)

print("Submission written successfully")
